from pathlib import Path
import json,hashlib
W=Path(__file__).resolve().parent;ROOT=W.parents[1];R=W/'runtime';read=lambda p:json.loads(p.read_text('utf8'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();bound=lambda p:{'path':p.relative_to(ROOT).as_posix(),'sha256':sha(p)}
cases=[];boards=[]
for name,targets in(('recoil',(90,91)),('settle',(138,139))):
 stem=f'nana_fourth_{name}28';e=read(R/(stem+'_watch')/'evidence.json');p=read(R/(stem+'_play')/'evidence.json');m=read(R/(stem+'_review')/'manifest.json');assert p['actual_window_recording']and not p['simulated_video']and not p['memory_written']and not p['save_keys_sent']and not p['error']and not e['unverified_events']
 dirs={str(n):sorted({q['facing_raw']for q in e['events']if q['verified']and q['bank']==0 and q['frame']==n})for n in targets};assert all(v==[0,64]for v in dirs.values())
 views=[bound(Path(q['path']))for q in m['pages']];boards.extend(views);cases.append({'name':name,'frames':p['frames'],'target_refs_both_directions':dirs,'verified_bank_frames':e['verified_bank_frames'],'unverified_events':e['unverified_events'],'resident_assets_still_exact':e['resident_assets_still_exact'],'watch':bound(R/(stem+'_watch')/'evidence.json'),'recording':bound(R/(stem+'_play')/'evidence.json'),'actual_video':bound(R/(stem+'_play')/'play.webp'),'review_manifest':bound(R/(stem+'_review')/'manifest.json'),'root_actually_viewed_boards':views})
assert len(boards)==8
r={'disc':e['disc'],'disc_sha256':e['disc_sha256'],'session':e['session'],'form':'Nana full Fourth armor, both directions','resident_assets':e['resident_assets'],'cases':cases,'captured_windows':sum(q['frames']for q in cases),'root_actually_viewed_board_count':8,'findings':['새사격 후속90/91과 새회복138/139를 포스아머 양방향에서 실제 관측했고 해당 순간RAM/GPU 디코드가 일치했다.','8개 실제 시간순 화면판에서 머릿결/옷 주름이 유지되며 추가 확정 몸체 분리·규모 급변을 찾지 못했다.'],'limits':['포스아머 전파츠 상태의 제한된 사격/프로스트 타워 검증이다. 기본형/부분파츠/기타캐릭터 전수 실기가 아니다.','463캡처 전체를 직접 열람한 것이 아니라 해당구간8개 시간순 비교판을 직접 열람했다. 원래 무기이펙트로 몸이 가려지는 프레임이 있다.','새로 제작중인133/135/136/137 등장은 RN28에 미포함이다.'],'protection_before':bound(W/'protection_checkpoint37.json'),'protection_after':bound(W/'protection_checkpoint38.json'),'original_save_keys_sent':False,'process_memory_written':False,'session_closed':True,'whole_project_complete':False,'final_user_accepted':False};assert r['captured_windows']==463
out=R/'nana_fourth_latest28_summary.json';assert not out.exists();out.write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n','utf8');cp=W/'root_review_checkpoint123.json';assert not cp.exists();cp.write_text(json.dumps({'reviewer':'root','kind':'actual game window chronological crop boards','summary':bound(out),'actually_viewed':boards,'findings':r['findings'],'limits':r['limits']},ensure_ascii=False,indent=2)+'\n','utf8');print(json.dumps({'summary_sha256':sha(out),'root_review_sha256':sha(cp),'windows':463,'reviewed_boards':8}))
